//! What is left of app startup after the shared parts moved to
//! `picodroid_core::boot`: this family's APK blob and its post-run idle loop.

// APK accessor, generated by build.rs from the PICODROID_APK_PATH env var.
// Defines: pub fn apk_data() -> &'static [u8]. Embedded builds get an empty
// slice (APK lives in PAPK_FLASH); sim builds read the .papk from disk at
// startup so Java-only changes don't force a Rust rebuild; other host builds
// (cargo test) embed it via include_bytes!.
//
// This is the one piece of startup that cannot move: where the app bytes come
// from is a property of the family's flash layout and build.
#[cfg(not(test))]
include!(concat!(env!("OUT_DIR"), "/apk_data.rs"));

// `hal/rp/boot.rs` runs an installed PAPK through this rather than the
// built-in one, so the old name is kept as the local spelling.
#[cfg(not(test))]
pub use picodroid_core::boot::run_app as run_jvm_with;

/// Run the JVM with the built-in APK.
#[cfg(not(test))]
#[cfg_attr(not(feature = "sim"), allow(dead_code))]
pub fn run_jvm() {
    run_jvm_with(apk_data());

    // On device the JVM task must not return — its stack is the app's. Park
    // it instead. The simulator falls out of `main` and exits, which is what
    // the sim test harness expects.
    #[cfg(all(not(feature = "sim"), feature = "family-rp"))]
    loop {
        freertos_rust::CurrentTask::delay(freertos_rust::Duration::ms(60_000));
    }
}
